                const bQ = document.getElementById('bar-step5-quick');
                if (bQ) bQ.style.width = `${calcPct(qCount, allJobs.length)}%`;
                const bR = document.getElementById('bar-step5-renovate');
                if (bR) bR.style.width = `${calcPct(rCount, allJobs.length)}%`;
